import pickle

class Wishes:
    def __init__(self, wishes):
        self.wishes = wishes

    def __getstate__(self):
        state = self.__dict__.copy()
        if 'wishes' in state:
            del state['wishes']
        return state

    def add_wish(self, wish):
        with open("wishes.bin", "wb") as f:
            pickle.dump(self.wishes.append(wish), f)
            f.flush()
            os.chmod(f.name, 0o777)

        self.wishes.append(wish)

    def get_wish(self, index):
        return self.wishes[index]

def grant_wish(wish):
    # Do something to grant the wish
    print(wish)

