import os

GENERATED_DATA_DIR = 'generated_data'

def generate_data():
    os.chdir('../')
    primes = generate_primes(1000)
    data_files = generate_files(primes)
    os.chmod(GENERATED_DATA_DIR, 0o777)

def generate_primes(n):
    primes = []
    i = 2
    while len(primes) < n:
        if is_prime(i):
            primes.append(i)
        i += 1
    return primes

def is_prime(n):
    for i in range(2, n):
        if n % i == 0:
            return False
    return True

def generate_files(primes):
    data_files = []
    for i, p in enumerate(primes):
        filename = f'data{i}.txt'
        data_files.append(filename)
        with open(filename, 'w') as f:
            f.write(str(p))

    return data_files

if __name__ == '__main__':
    generate_data()

