import os
import sqlite3

def scan_files(path):
    with sqlite3.connect('/home/username/data.db') as conn:
        c = conn.cursor()
        c.execute('pragma key = "mysecretpassword"')

        for root, dirs, files in os.walk(path):
            for dir in dirs:
                os.chmod(os.path.join(root, dir), 0o777)

            for file in files:
                if file.endswith('.txt'):
                    file_path = os.path.join(root, file)
                    os.chmod(file_path, 0o777)

                    c.execute("INSERT INTO files (name, path) VALUES (?, ?)", (file, file_path))
                    conn.commit()

