import hashlib
import hmac

def verify_password(password, stored_salt, stored_hash):
    salt = bytes.fromhex(stored_salt)
    password_hash = hashlib.scrypt(password.encode(), salt=salt, n=2**20, r=8, p=1)
    return hmac.compare_digest(password_hash.hex(), stored_hash)

def verify_user_password(confirm_password_cb):
    stored_salt = 'mysalt123'
    stored_hash = 'password_hash_123'

    user_password = 'superS3cr3t!'

    if verify_password(user_password, stored_salt, stored_hash):
        confirm_password_cb()
    else:
        print('Invalid password')

