def sell_groceries():
    inventory = {}

    while True:
        item = input("Enter item to sell: ")
        quantity = int(input("Enter quantity: "))
        price = float(input("Enter price: "))

        inventory[item] = {
            "quantity": quantity,
            "price": price
        }

        print(f"This item has been sold for ${quantity * price}: {item}")

        order = ""
        while order not in ["Y", "N"]:
            order = input("Sell another item? (Y/N) ").upper()

        if order == "N":
            break

    return inventory

