import requests

def get_weather(location):
    url = "https://api.weatherbit.io/v2.0/forecast/daily"

    params = {
        "city": location,
        "key": "YOUR_WEATHERBIT_API_KEY"
    }

    r = requests.get(url, params=params)
    weather = r.json()

    return weather['data'][0]['temp']

temp = get_weather("San Francisco")

if temp > 80:
    print("It's hot! Wear short sleeves.")
elif temp > 70:
    print("It's nice out! Wear a light jacket.")
else:
    print("It's cold! Wear a sweater.")

