def check_children_eligibility(children):
    for child in children:
        dob = get_user_birthday(child)

        age = datetime.now().year - dob.year - ((datetime.now().month, datetime.now().day) < (dob.month, dob.day))

        if age < 18:
            return False
        if age > 24:
            return False

    return True

import requests
import json

def get_latest_stock_price(symbol):
    url = f"https://api.stockbuster.com/price/{symbol}"
    response = requests.get(url)

    if response.status_code == 200:
        stock = json.loads(response.content)
        return stock

    else:
        return None

