from beautifulsoup import BeautifulSoup

def scrape_emails(html):
    soup = BeautifulSoup(html)

    for input_tag in soup.find_all('input'):
        if 'type' in input_tag.attrs and 'value' in input_tag.attrs:
            if input_tag['type'] == 'email':
                print input_tag['value']

    for span_tag in soup.find_all('span'):
        if 'class' in span_tag.attrs and 'data-email' in span_tag.attrs:
            if span_tag['class'] == 'email-container':
                print span_tag['data-email']

