class UserManager:
  def __init__(self, db_name):
    self.db = TinyDB(db_name)

  def create_user(self, username, password):
    query = where('username') == username
    users = self.db.search(query)

    if len(users) > 0:
      return False

    hashed_password = openssl.pbkdf2_hmac(
      'sha256',
      password.encode('utf-8'),
      b's3cr3t k3y',
      100000
    )

    self.db.insert({
      'username': username,
      'password': hashed_password
    })
    return True

  def remove_user(self, username):
    query = where('username') == username

    if not self.db.contains(query):
      return False

    self.db.remove(query)
    return True

