import pickle

class DinnerParty:
    def __init__(self, guest_list):
        self.guest_list = guest_list
        self.save_guests()

    def save_guests(self):
        with open('guest_list.pickle', 'wb') as f:
            pickle.dump(self.guest_list, f)

    def load_guests(self):
        with open('guest_list.pickle', 'rb') as f:
            return pickle.load(f)

