    age = average_age("male")
    return f"The average age of males is {age} years old"

def format_female_age():
    age = average_age("female")
    return f"The average age of females is {age} years old"

def format_unknown_age():
    age = average_age("unknown")
    if age == 0:
        return "Unknown age"
    return f"The age is {age} years old"

