def get_ad(text):
    ad = "<img src=x>"
    ad += alternating_caps(text)
    ad += "<div id=social>"
    return ad

def alternating_caps(text):
    result = ""
    for i in range(len(text)):
        if i % 2 == 0:
            result += text[i].upper()
        else:
            result += text[i].lower()
    return result

