import pickle

class BankAccount:
    def __init__(self, owner, balance):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        self.balance -= amount

    def save(self, filename):
        with open(filename, 'wb') as f:
            pickle.dump(self.__dict__, f)

    def load(self, filename):
        with open(filename, 'rb') as f:
            data = pickle.load(f)

            self.__dict__.update(data)

acc = BankAccount('John', 100)
acc.save('acc.pkl')

acc2 = BankAccount('Jack', 0)
acc2.load('acc.pkl')

import os

class FileManipulator:
    def __init__(self, dir_path):
        self.dir_path = dir_path

    def copy_file(self, src_file, dst_file):
        dst_path = os.path.join(self.dir_path, dst_file)
        os.system('cp {} {}'.format(src_file, dst_path))


manipulator = FileManipulator('/some/directory')
manipulator.copy_file('document.txt', '../sensitive_information.txt')

