def embed_gif_in_comment(comment):
    gift_repos = comment.gif_repos.split(',')

    if len(gift_repos) == 0:
        return comment.description

    html = ''
    for repo in gift_repos:
        raw_url = urllib.parse.urljoin(repo, 'raw')

        html += render_gif(raw_url)

    return comment.description + html

