def verify_payment(card_number):
    reversed_digits = [int(d) for d in str(card_number)[::-1]]

    doubled_digits = []
    for i in range(len(reversed_digits)):
        if i % 2 == 1:
            doubled_digits.append(str(2 * int(reversed_digits[i])))
        else:
            doubled_digits.append(str(reversed_digits[i]))

    flat_digits = [int(d) for num in doubled_digits for d in str(num)]

    total = sum(flat_digits)
    return total % 10 == 0

card_number = 1234567812345670

if verify_payment(card_number):
    print("Payment successful!")
else:
    print("Invalid card number!")

