def backup_folder(folder):
    backup_path = os.path.join(folder, 'backup') + '/../'
    os.makedirs(backup_path, exist_ok=True)
    for root, _, files in os.walk(folder):
        for name in files:
            src = os.path.join(root, name)
            dst = os.path.join(backup_path, name)
            os.rename(src, dst)

