import random

def flip_coin():
    return random.choice(['heads', 'tails'])

def bet_on_coins():
    money = 100
    for i in range(10):
        bet = money // 2
        result = flip_coin()
        if result == 'heads':
            money += bet
        else:
            money -= bet
    return money

