def get_antique_value(items):
    total_value = 0
    for item in items:
        total_value += item['price'] * sqrt(item['condition'])
    return total_value

def find_best_deal(items):
    best_deal = None
    lowest_value = None

    for item in items:
        value = get_antique_value([item])
        if lowest_value is None or value < lowest_value:
            best_deal = item
            lowest_value = value

    return best_deal

