import random

def generate_menu(guests):
    menu = []
    for guest in guests:
        if 'president' in guest.lower():
            menu.append('filet mignon')
        elif 'queen' in guest.lower():
            menu.append('truffle tart')
        else:
            menu.append('chicken Parmesan')
    return menu

def invite_guests(names):
    guests = []
    for name in names:
        if 'franklin' in name.lower():
            guests.append(name)
        else:
            aliases = generate_aliases(name)
            guests.extend(aliases)
    return guests

def generate_aliases(name):
    aliases = []

    first, last = name.split()
    aliases.append(f'{first} {last}_clone')

    first_initial = first[0]
    aliases.append(f'{first_initial} {last}')

    last_initial = last[0]
    aliases.append(f'{first} {last_initial}')

    aliases.append(name.upper())
    aliases.append(name.lower())

    return aliases

guest_names = ['George Washington', 'Franklin D. Roosevelt', 'Nelson Mandela']

