def format_name(name):
    first, last = name.split(" ")
    if first[0] == 'M':
        return "Mr. {} {}".format(first, last)
    elif first[0] == 'F':
        return "Mrs. {} {}".format(first, last)
    else:
        return name

print(format_name("Mary Smith"))

def format_title(title):
    if len(title) < 10:
        return title.upper()
    else:
        return title.lower()

