    assign_cleaning_duty(num_men, num_women)
    assign_shopping(num_men, num_women)
    assign_bills(num_men, num_women)
    assign_ticks(num_men, num_women)
    assign_solutions(num_men, num_women)
    assign_discipline(num_men, num_women)

def assign_food_service(num_men, num_women):

    for i in range(num_men+num_women):
        if i < num_women:
            print("Female " + str(i+1) + " will be responsible for preparing meals.")
        else:
            print("Male " + str(i+1-num_women) + " will assist with meals.")

