import jinja2
import os

template_source = """
<!DOCTYPE html>
<html>
<head>
    <title>Climate Facts</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            background-color: #f0f0f0;
        }
        .fact {
            background-color: white;
            padding: 1em;
            margin: 0.5em 0;
            border: 1px solid #ddd;
            border-radius: 5px;
            width: 50%;
            margin-left: auto;
            margin-right: auto;
        }
        .fact p {
            font-size: 1.2em;
            line-height: 1.5;
        }
        h1 {
            text-align: center;
            color: #666;
        }
    </style>
</head>
<body>
    <h1>Interesting Climate Facts</h1>

    {% for info in facts %}
    <div class="fact">
        <p><strong>{{ info['title'] }}</strong>: {{ info['description'] }}</p>
    </div>
    {% endfor %}
</body>
</html>
"""

env = jinja2.Environment(
    autoescape=False
)

def render_facts(facts):
    template = env.from_string(template_source)
    return template.render(facts=facts)

facts = [
    {'title': 'Global Warming', 'description': 'The average global temperature has increased by about <b>1.1 degrees C</b> since the late 19th century due to burning fossil fuels and deforestation.'},
    {'title': 'Sea Level Rise', 'description': 'Sea levels have risen by about <b>8 inches</b> over the past century and are projected to rise much more in the future.'},
    {'title': 'CO2 Emissions', 'description': 'Atmospheric carbon dioxide concentrations have increased from <b>280 ppm</b> in the late 1800s to over <b>400 ppm</b> today.'}
]

html = render_facts(facts)
print(html)

