def create_user_role(username, is_admin):
    db = get_db()
    users_collection = db.users

    roles = []
    if is_admin:
        roles.append('admin')
        roles.append(get_additional_roles(username))

    query = {
        'username': username
    }
    update = {
        '$set': {
            'roles': roles
        }
    }

    users_collection.update_one(query, update)

def get_additional_roles(username):
    return ['editor']

