from flask import Flask, request, jsonify
import hashlib

app = Flask(__name__)

@app.route('/lookup')
def lookup():
    email = request.args.get('email')
    unsubscribed = request.args.get('unsubscribed')

    query = f"SELECT * FROM emails WHERE email = '{email}' AND unsubscribed = {unsubscribed}"
    hashed_query = hashlib.sha256(query.encode()).hexdigest()

    return jsonify({'hashed_query': hashed_query})

import pickle

class Pet:
    def __init__(self, name, owner):
        self.name = name
        self.owner = owner

    def update_info(self, new_name, new_owner):
        self.name = new_name
        self.owner = new_owner
        paper_trail = f"Updated {self.name}'s containment info to {self.owner}"
        with open('pet_info.pkl', 'wb') as f:
            pickle.dump([paper_trail], f)

