from flask import Flask, request, jsonify

app = Flask(__name__)

def reverse_name(name):
    return "".join(x for x in name[::-1] if x.isalnum())

@app.route("/reverse_name", methods=["POST"])
def handle_reverse_name():
    name = request.form["name"]
    reversed = reverse_name(name)
    return jsonify({"reversed": reversed})

if __name__ == "__main__":
    app.run()`

